// Configure Google News RSS query (zero API keys required)
const query = 'AI agents';
const maxItems = 5;
const rssUrl = `https://news.google.com/rss/search?q=${encodeURIComponent(query)}&hl=en-US&gl=US&ceid=US:en`;

return [{ json: { query, maxItems, rssUrl } }];

// Parse Google News RSS items and inspect CBMi protobuf tokens offline first
const cfg = $('Configure News Topic').first().json;
const maxItems = Number(cfg.maxItems || 5);
const xml = String($input.first().json.data ?? $input.first().json.body ?? '');

function extractToken(rawUrl) {
  const m = String(rawUrl || '').match(/news\.google\.com\/(?:rss\/)?(?:articles|read)\/([A-Za-z0-9_-]+)/);
  return m ? m[1] : null;
}

function tryLegacyDecode(token) {
  if (!token) return null;
  const b64 = token.replace(/-/g, '+').replace(/_/g, '/') + '='.repeat((4 - (token.length % 4)) % 4);
  const buf = Buffer.from(b64, 'base64');
  const txt = buf.toString('latin1');
  if (txt.includes('AU_yqL')) return null;
  const hit = txt.match(/https?:\/\/[^\x00-\x1f\x7f-\xff"<>\s]+/);
  return hit ? hit[0] : null;
}

const out = [];
for (const m of xml.matchAll(/<item>([\s\S]*?)<\/item>/g)) {
  if (out.length >= maxItems) break;
  const block = m[1];
  const getTag = (tag) => {
    const hit = block.match(new RegExp(`<${tag}[^>]*>([\\s\\S]*?)<\\/${tag}>`, 'i'));
    return hit ? hit[1].replace(/<!\[CDATA\[|\]\]>/g, '').trim() : '';
  };
  const gnewsLink = getTag('link');
  const token = extractToken(gnewsLink);
  const legacyUrl = tryLegacyDecode(token);
  out.push({
    json: {
      title: getTag('title'),
      pubDate: getTag('pubDate'),
      source: getTag('source'),
      gnewsLink,
      token,
      splashUrl: token ? `https://news.google.com/articles/${token}` : gnewsLink,
      decodedUrl: legacyUrl,
      needsLiveExchange: Boolean(token && !legacyUrl),
      method: legacyUrl ? 'legacy-protobuf-base64' : 'pending-Fbv4je',
    },
  });
}

return out.length ? out : [{ json: { status: 'no_rss_items', needsLiveExchange: false } }];

// Extract data-n-a-sg and data-n-a-ts from DotsSplashUi HTML and prepare Fbv4je RPC
const splashItems = $input.all();
const upstreamItems = $('Needs Live Fbv4je Exchange?').all();
const out = [];

for (let i = 0; i < splashItems.length; i++) {
  const html = String(splashItems[i].json.data ?? splashItems[i].json.body ?? '');
  const meta = (upstreamItems[i] && upstreamItems[i].json) ? upstreamItems[i].json : {};
  const sg = (html.match(/data-n-a-sg="([^"]+)"/) || [])[1] || '';
  const ts = (html.match(/data-n-a-ts="([^"]+)"/) || [])[1] || '';

  if (!sg || !ts || !meta.token) {
    out.push({
      json: {
        ...meta,
        fReq: '',
        canCallFbv4je: false,
        method: 'fallback-missing-splash-params',
      },
    });
    continue;
  }

  const inner = [
    'garturlreq',
    [['X', 'X', ['X', 'X'], null, null, 1, 1, 'US:en', null, 1, null, null, null, null, null, 0, 1], 'X', 'X', 1, [1, 1, 1], 1, 1, null, 0, 0, null, 0],
    meta.token,
    Number(ts),
    sg,
  ];
  const fReq = JSON.stringify([[['Fbv4je', JSON.stringify(inner), null, 'generic']]]);
  out.push({
    json: {
      ...meta,
      fReq,
      canCallFbv4je: true,
    },
  });
}
return out;

// Parse garturlres canonical publisher URL from Google DotsSplashUi Fbv4je response
const rpcItems = $input.all();
const reqMeta = $('Build Fbv4je Signature Payload').all();

return rpcItems.map((item, idx) => {
  const raw = String(item.json.data ?? item.json.body ?? '');
  const meta = (reqMeta[idx] && reqMeta[idx].json) ? reqMeta[idx].json : {};
  const match = raw.match(/\[\s*\\"garturlres\\"\s*,\s*\\"(https?:[^"\\]+)\\"/);
  let decodedUrl = meta.decodedUrl || meta.gnewsLink || null;
  let method = meta.method || 'fallback';

  if (match && match[1]) {
    try {
      decodedUrl = JSON.parse(`"${match[1]}"`);
      method = 'batchexecute-Fbv4je';
    } catch {
      decodedUrl = match[1];
      method = 'batchexecute-Fbv4je-raw';
    }
  }

  return {
    json: {
      title: meta.title || '',
      source: meta.source || '',
      pubDate: meta.pubDate || '',
      gnewsLink: meta.gnewsLink || '',
      decodedUrl,
      method,
    },
  };
});

return $input.all().map((item) => ({
  json: {
    title: item.json.title || '',
    source: item.json.source || '',
    pubDate: item.json.pubDate || '',
    gnewsLink: item.json.gnewsLink || '',
    decodedUrl: item.json.decodedUrl || item.json.gnewsLink || null,
    method: item.json.method || 'legacy-protobuf-base64',
  },
}));
